'use strict'

async function runWithRetry (task, state) {
  try {
    return await task()
  } catch (error) {
    if (state.remaining > 0) {
      state.remaining--
      return runWithRetry(task, state)
    }
    throw error
  }
}

async function consumeFirst (queue) {
  if (queue.shift()) {
    return queue.length
  }
  return -1
}

async function chooseBranch (state) {
  if (state.usePrimary) {
    return 'primary'
  } else {
    return 'fallback'
  }
}

async function runAfterSetup (task) {
  try {
    return await task()
  } catch (error) {
    return error.message
  }
}

async function runFromStart (task) {
  'use strict'

  const value = 'passed'
  return task(value)
}

class ContextRunner {
  async run (state) {
    if (state.shouldContinue) {
      return 'continued'
    }
  }
}

module.exports = { chooseBranch, consumeFirst, ContextRunner, runAfterSetup, runFromStart, runWithRetry }
